import sys
from collections import defaultdict, deque

input = sys.stdin.read
data = input().split()

index = 0

def read_int():
    global index
    result = int(data[index])
    index += 1
    return result

def read_ints():
    global index
    result = list(map(int, data[index:index + read_int()]))
    index += read_int()
    return result

def solve(n, m, edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    degree_mod3 = [0] * n
    for i in range(n):
        degree_mod3[i] = len(graph[i]) % 3

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (degree_mod3[i] + degree_mod3[j] + degree_mod3[k]) % 3 == 0:
                    return True, [i + 1, j + 1, k + 1]
    return False, []

t = read_int()
index = 0

for _ in range(t):
    n, m = read_ints()
    edges = [read_ints() for _ in range(m)]
    result, vertices = solve(n, m, edges)
    if result:
        print("Yes")
        print(len(vertices))
        print(*vertices)
    else:
        print("No")
    if _ < t - 1:
        print()
